#!/usr/bin/env python3
from __future__ import annotations

import argparse
import base64
import hashlib
import json
import py_compile
import shutil
from datetime import datetime
from pathlib import Path

FILES = {
  "training/train_target_protected_scan_calibrator_ablation.py": "",
  "scripts/run_bc_dpg_v3_ablation.py": "",
  "scripts/summarize_bc_dpg_v3_ablation.py": "",
  "features/__init__.py": "IiIiRmVhdHVyZSBleHRyYWN0aW9uIHV0aWxpdGllcyBmb3IgcmFkYXIgbXVsdGktZG9tYWluIGV4cGVyaW1lbnRzLiIiIgo=",
  "features/polarimetric_rd.py": "",
  "scripts/test_polarimetric_features_v1.py": "",
  "scripts/audit_polarimetric_features_v1.py": "",
  "configs/bc_dpg_v3_ablation_polar_stage1.yaml": ""
}
EXPECTED_HASHES = {
  "training/train_target_protected_scan_calibrator_ablation.py": "e1ef0455c47aba7aa528bbd367eb0f559767f9b3f1b329ca32e032b1046c5ebb",
  "scripts/run_bc_dpg_v3_ablation.py": "fba41958aebbbf51d0ec80c53c6ed573cb0ff28ca6f790e02cf8545c7c12f733",
  "scripts/summarize_bc_dpg_v3_ablation.py": "0c85f700c748c74e1cb06a8b285e0ff6f7f7adb6503c5eace5c433593cf361e2",
  "features/__init__.py": "cbc48b055fef209f194309d86830d0d5d21fbdf24084b8d292352ddbd25bdcc2",
  "features/polarimetric_rd.py": "2b1dbc92aa10882295df9186d92309d50ce7971d424c9f2d9732b73702b3f416",
  "scripts/test_polarimetric_features_v1.py": "6f6227c6b87deb2d393564a9f8e12a53c58d371a1c9ec47ef844ca6b1617e25c",
  "scripts/audit_polarimetric_features_v1.py": "f9d813d4c1f04618e06bded49c513234ebab92bd35b34a29e65feb5f390bcd41",
  "configs/bc_dpg_v3_ablation_polar_stage1.yaml": "35f39c16be1d8bbc89cf7320ddaa88b32245d98e4ec57f2d9f4a6c05be8b9b5c"
}

REQUIRED_PROJECT_FILES = (
    "models/target_protected_scan_calibrator.py",
    "training/train_target_protected_scan_calibrator.py",
    "datasets/detection_dataset_v2.py",
    "datasets/detection_dataset_v3.py",
)


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(
        description=(
            "Install BC-DPG-FCN v3 ablation and explicit "
            "polarimetric feature Stage 1 files."
        )
    )
    parser.add_argument(
        "--force",
        action="store_true",
        help="Overwrite an existing installed file after backing it up.",
    )
    return parser.parse_args()


def sha256_bytes(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def main() -> None:
    args = parse_args()
    project_root = Path(__file__).resolve().parent

    missing = [
        path
        for path in REQUIRED_PROJECT_FILES
        if not (project_root / path).is_file()
    ]
    if missing:
        print("[错误] 当前脚本不在雷达项目根目录，或工程文件不完整。")
        print("缺少：")
        for item in missing:
            print(f"  - {item}")
        print("\n请把本脚本直接放到 balloon_radar_project 根目录后运行。")
        raise SystemExit(2)

    timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    backup_root = (
        project_root
        / "backups"
        / f"bc_dpg_v3_ablation_polar_stage1_{timestamp}"
    )
    installed = []
    backed_up = []

    for relative_path, encoded in FILES.items():
        target = project_root / relative_path
        content = base64.b64decode(encoded.encode("ascii"))
        actual_hash = sha256_bytes(content)
        expected_hash = EXPECTED_HASHES[relative_path]
        if actual_hash != expected_hash:
            raise RuntimeError(
                f"内置文件校验失败：{relative_path}"
            )

        if target.exists():
            existing_hash = sha256_bytes(target.read_bytes())
            if existing_hash == expected_hash:
                print(f"[跳过] 已是目标版本：{relative_path}")
                continue
            if not args.force:
                print(
                    f"[错误] 文件已存在且内容不同：{relative_path}\n"
                    "如确认覆盖，请重新执行：\n"
                    "  python apply_bc_dpg_v3_ablation_polar_stage1.py --force"
                )
                raise SystemExit(3)
            backup = backup_root / relative_path
            backup.parent.mkdir(parents=True, exist_ok=True)
            shutil.copy2(target, backup)
            backed_up.append(relative_path)

        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_bytes(content)
        installed.append(relative_path)
        print(f"[写入] {relative_path}")

    python_files = [
        project_root / path
        for path in FILES
        if path.endswith(".py")
    ]
    for path in python_files:
        py_compile.compile(
            str(path),
            doraise=True,
        )
        print(f"[语法通过] {path.relative_to(project_root)}")

    install_record = {
        "installed_at": datetime.now().isoformat(),
        "project_root": str(project_root),
        "installed_files": installed,
        "backed_up_files": backed_up,
        "file_hashes": EXPECTED_HASHES,
    }
    record_dir = (
        project_root
        / "results"
        / "data_audit"
        / "bc_dpg_v3_ablation_polar_stage1"
    )
    record_dir.mkdir(parents=True, exist_ok=True)
    record_path = record_dir / "install_record.json"
    record_path.write_text(
        json.dumps(
            install_record,
            ensure_ascii=False,
            indent=2,
        ),
        encoding="utf-8",
    )

    print("\n" + "=" * 82)
    print("安装完成：BC-DPG-FCN v3消融 + 显式极化特征 Stage 1")
    print(f"工程目录：{project_root}")
    if backed_up:
        print(f"备份目录：{backup_root}")
    print(f"安装记录：{record_path}")
    print("=" * 82)
    print("\n建议按顺序执行：")
    print("1. python scripts/test_polarimetric_features_v1.py")
    print(
        "2. python scripts/audit_polarimetric_features_v1.py "
        "--manifest-path "
        "results/data_audit/dataset_v4_multifold/fold_01_manifest.csv "
        "--max-per-class 20"
    )
    print(
        "3. python scripts/run_bc_dpg_v3_ablation.py "
        "--folds 1 --modes full no_scan_context "
        "no_target_protection --smoke"
    )


if __name__ == "__main__":
    main()
